head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > groupby]<br/>Body Column 을 기준으로 데이터를 그룹핑하여 Group Header/Footer 함께 표시합니다.",
    "validation" : [
        "GroupBy 기능이 적용되고 groupbyZone=true 이면 그룹핑된 Column 에 Group FilterList 기능이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : groupbyZone=true 전제 그리드
scwin.comp_init = async function () {
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 고정속성 groupbyZone=true, useFilterList=true, customFilterBox=true 그리드 (등급 컬럼 기준 groupby)\n[절차] [groupby 실행] 클릭 -> 등급(2) 기준 그룹핑 + groupbyZone 영역에 그룹핑 Column 표시\n[확인] 그룹핑된 Column 에 Group FilterList(필터 아이콘/목록) 적용 여부를 실측 출력에서 확인 (적용/미적용 관찰)"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (Body Column id 와 동일한 컬럼 id)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="score" name="score" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "region": "부산", "dept": "영업", "grade": "B", "score": 30 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 10 },
        { "region": "부산", "dept": "개발", "grade": "B", "score": 50 },
        { "region": "서울", "dept": "영업", "grade": "A", "score": 20 },
        { "region": "서울", "dept": "개발", "grade": "B", "score": 40 },
        { "region": "부산", "dept": "영업", "grade": "A", "score": 60 }
    ];
    dlt_bind.setJSON(jsonData, false);

    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 : groupbyZone + FilterList 전제 속성 고정
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id=""';
    strTarget += ' groupbyZone="true" useFilterList="true" customFilterBox="true"';
    strTarget += ' style="width:640px;height:900px;">';
    strTarget += '<w2:caption style="" id="caption1" value="groupbyZone Group FilterList 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="지역(0)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="부서(1)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol3" value="등급(2)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="점수(3)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="region" dataList="region"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="grade" dataList="grade"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="score" dataList="score"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// depth 계층 가시화 들여쓰기 : depth×2칸 순수 공백
scwin._depthMark = function (depth) {
    return "  ".repeat(depth);
};

// groupby 후 tbody 렌더 Row 를 화면 순서(위->아래) 그대로 순회하여 표시 텍스트 반환
//  - colSpan 을 누적해 Body 컬럼 수(4) 에 도달하면 종료 / 숨김 filler Row 제외 / nbsp -> 공백
scwin.readScreenLines = function (depthCount) {
    depthCount = depthCount || 1;
    let tbody = document.getElementById(target1.id + "_body_tbody");
    let trs = tbody.querySelectorAll("tr");
    let screenLines = [];
    for (let i = 0; i < trs.length; i++) {
        let tr = trs[i];
        if (tr.style.display === "none" || tr.className.indexOf("w2grid_hidedRow") >= 0) continue;
        let cells = [];
        let colAcc = 0;
        let tdList = tr.querySelectorAll("td");
        for (let k = 0; k < tdList.length && colAcc < 4; k++) {
            let td = tdList[k];
            if (td.style.display === "none") continue;
            colAcc += parseInt(td.getAttribute("colSpan") || "1", 10);
            cells.push((td.textContent || "").replace(/ /g, " ").trim());
        }
        let rowDepth = depthCount;
        let gtd = tr.querySelector("td[class*='w2grid_groupby_depth_']");
        if (gtd) {
            let m = gtd.className.match(/w2grid_groupby_depth_(\d+)/);
            if (m) rowDepth = parseInt(m[1], 10);
        }
        screenLines.push(scwin._depthMark(rowDepth) + cells.join(" | "));
    }
    return screenLines;
}

// 그룹핑된 Column 에 Group FilterList 기능이 적용됐는지 실측
//  - groupbyZone 영역에 그룹핑 Column(칩) 표시 여부
//  - 그룹핑 Column 칩 클릭 시 Group FilterList(목록 DOM / groupbyFilterList 객체) 생성 여부
scwin.readGroupFilterList = function () {
    let zone = document.getElementById(target1.id + "_groupbyZone_div");
    let zoneShown = zone ? (zone.offsetParent !== null || zone.offsetHeight > 0) : false;
    // groupbyZone 영역 내 그룹핑 Column 칩
    let zoneCols = zone ? zone.querySelectorAll(".w2grid_groupbyZone_column") : [];
    let chipLabel = zone ? zone.querySelector(".w2grid_groupbyZone_column_labelDiv") : null;

    // 그룹핑 Column 칩(라벨) 클릭 -> 해당 Column 의 Group FilterList 표시/생성
    if (chipLabel) {
        chipLabel.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
    }
    let listObj = (typeof target1.groupbyFilterList !== "undefined" && target1.groupbyFilterList) ? "생성됨" : "미생성";
    let listDom = document.querySelector(".w2grid_groupbyZone_list") ? "있음" : "없음";

    return {
        zoneShown: zoneShown ? "표시" : "미표시",
        zoneColCnt: zoneCols ? zoneCols.length : 0,
        chip: chipLabel ? "있음" : "없음",
        listObj: listObj,
        listDom: listDom
    };
}



// groupby 실행 : groupbyZone=true 상태에서 등급 기준 그룹핑 후 Group FilterList 적용 여부 실측
scwin.btn_groupby_onclick = function () {
    // sortIndex/sortOrder 고정 : 등급(2) 오름차순, groupbyHeader 로 토글+그룹명 최소 표시
    let gbOptions = {
        sortIndex: [2],
        sortOrder: [1],
        groupbyHeader: [
            { inputType: "expression", expression: "toggle() + depthStr()", colSpan: 4, align: "left" }
        ]
    };
    target1.groupby(gbOptions);

    let g = scwin.readGroupFilterList();
    let screenLines = scwin.readScreenLines(gbOptions.sortIndex.length);

    let out = "[groupby 실행 - groupbyZone Group FilterList 적용 여부]"
        + " groupbyZone영역=" + g.zoneShown
        + " | 그룹핑Column 칩 수=" + g.zoneColCnt
        + " | 칩=" + g.chip
        + " | 칩 클릭후 Group FilterList 객체=" + g.listObj
        + " | 목록 DOM=" + g.listDom
        + "\n=> Group FilterList " + ((g.listObj === "생성됨" || g.listDom === "있음") ? "적용됨(정상)" : "미적용(가이드 규정 미동작 관찰)")
        + "\n[화면 표시 순서]\n" + (screenLines.length ? screenLines.join("\n") : "(표시 Row 없음)");
    wf_body_bottom.getObj("scwin").setReturnValue(out);
}
